#define VP_NOFACE_TO_SLEEP    40   /* 连续无脸多少帧后进入 SLEEP */
#define VP_BLINK_TRACK        50   /* TRACK 态眨眼周期(帧) */
#define VP_BLINK_SLEEP        100  /* SLEEP 态慢眨周期(帧) */

=== 2) 新增 int bk7258_camera_velapet(void) ===
状态:enum { VP_SLEEP, VP_WAKE, VP_TRACK };
持久变量:
  int state = VP_SLEEP;
  int wake_ctr=0, noface_ctr=0, blink_ctr=0;
  /* gaze 状态,和 track 一模一样 */
  int dx_baseline=0; bool baseline_init=false;
  int smooth=0, last_gaze=0, dx_span_pos=TRACK_SPAN_MIN, dx_span_neg=TRACK_SPAN_MIN, miss_count=0;
