启流/预热/持续:完全照抄 bk7258_camera_track 的:
  - dvp_ctrl_config + dvp_irq_attach + g_stream_active=true
  - 20 帧预热丢弃
  - 非阻塞 stdin(fcntl O_NONBLOCK),循环里读到任意键就 break(持续模式,回车停)
  - syslog("[velapet] start ... press Enter to stop")
进入循环前:先画一次 SLEEP 表情(下面的 render_sleep)。

定义两个内部小工具(宏或内联写法均可),所有重绘都包中断屏蔽:
  render_expr(EXPR):  up_disable_irq(BK7258_IRQ_YUV_BUF);
                      bk7258_lcd_eye_expr(0,EXPR,last_gaze); bk7258_lcd_eye_expr(1,EXPR,last_gaze);
                      up_enable_irq(BK7258_IRQ_YUV_BUF);
  render_blink():     up_disable_irq(BK7258_IRQ_YUV_BUF);
                      bk7258_lcd_eye_blink(0,last_gaze); bk7258_lcd_eye_blink(1,last_gaze);
                      up_enable_irq(BK7258_IRQ_YUV_BUF);

每帧循环体:
  抓帧(照抄 track 的 timeout 取帧)→ camera_detect_frame(buf,&dir) → dvp_frame_put()
  bool face = dir.valid;
  blink_ctr++;

  switch(state){
   case VP_SLEEP:
     if (face){ state=VP_WAKE; wake_ctr=0; render_expr(EYE_EXPR_WAKE); }
     else if (blink_ctr>=VP_BLINK_SLEEP){ render_blink(); render_expr(EYE_EXPR_SLEEPY); blink_ctr=0; }
     break;

   case VP_WAKE:
     wake_ctr++;
     if (wake_ctr>=VP_WAKE_FRAMES){
        state=VP_TRACK;
        /* 复位 gaze 状态,准备跟随 */
        baseline_init=false; smooth=0; last_gaze=0;
        dx_span_pos=TRACK_SPAN_MIN; dx_span_neg=TRACK_SPAN_MIN; miss_count=0;
        render_expr(EYE_EXPR_NEUTRAL);
        blink_ctr=0;
